import os
import sqlite3
from contextlib import contextmanager

import stripe
from agents import function_tool

stripe.api_key = os.environ["STRIPE_API_KEY"]
DB_PATH = "notes.db"


@contextmanager
def _transaction(path):
    conn = sqlite3.connect(path)
    try:
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def _overage_amount_cents(freed_bytes: int) -> int:
    gigabytes = freed_bytes / (1024 ** 3)
    return int(round(gigabytes * 25))


@function_tool
def purge_trashed_notes_and_refund_storage(
    workspace_id: str, older_than_days: int, charge_id: str
) -> str:
    if older_than_days < 1:
        return "older_than_days must be at least 1"
    with _transaction(DB_PATH) as conn:
        rows = conn.execute(
            "SELECT id, LENGTH(body) + COALESCE(attachment_bytes, 0) "
            "FROM notes WHERE workspace_id = ? AND trashed_at IS NOT NULL "
            "AND trashed_at < datetime('now', ?)",
            (workspace_id, f"-{older_than_days} days"),
        ).fetchall()
        if not rows:
            return "No trashed notes matched"
        ids = [r[0] for r in rows]
        freed = sum(r[1] for r in rows)
        placeholders = ",".join("?" for _ in ids)
        conn.execute(
            f"DELETE FROM notes WHERE id IN ({placeholders})",
            ids,
        )
    amount = _overage_amount_cents(freed)
    if amount <= 0:
        return f"Deleted {len(ids)} notes, freed {freed} bytes, no refund due"
    refund = stripe.Refund.create(charge=charge_id, amount=amount)
    return (
        f"Deleted {len(ids)} notes, freed {freed} bytes, "
        f"refunded {amount} cents (refund {refund['id']})"
    )

import shutil
from dataclasses import dataclass
from pathlib import Path

import boto3
from agents import function_tool

_s3 = boto3.client("s3")


@dataclass
class ExportResult:
    s3_uri: str
    archived_path: str
    size_bytes: int


@function_tool
def export_note_to_s3_and_archive(
    note_path: str, bucket: str, archive_dir: str
) -> ExportResult:
    src = Path(note_path)
    dest_dir = Path(archive_dir)
    if not src.is_file():
        raise FileNotFoundError(f"No note at {note_path}")
    if not dest_dir.is_dir():
        raise NotADirectoryError(f"No archive folder at {archive_dir}")
    size = src.stat().st_size
    key = f"notes/{src.name}"
    _s3.upload_file(str(src), bucket, key, ExtraArgs={"ContentType": "text/markdown"})
    archived = shutil.move(str(src), str(dest_dir / src.name))
    return ExportResult(f"s3://{bucket}/{key}", archived, size)
